<template>
  <view class="page" v-if="authorized">
    <view class="hero"><text class="eyebrow">会员服务 · {{ currentDeptName }}</text><text class="title">会员购买记录</text><text class="subtitle">购买事实、收款与分批领取统一留痕</text></view>
    <view class="toolbar"><input v-model="keyword" placeholder="购买单号、顾客姓名或手机号" @confirm="load" /><button @tap="load">查询</button></view>
    <view class="actions"><button v-if="can('add')" class="primary" @tap="openCreate">＋ 新建购买单</button><button @tap="load">刷新</button></view>
    <view class="card" v-for="row in rows" :key="row.purchaseId">
      <view class="row-head"><text class="row-title">{{ row.purchaseNo || '-' }}</text><text class="tag">{{ customerTypeText(row.customerType) }}</text></view>
      <view class="row-main"><view><text class="customer">{{ row.customerName || '未登记顾客' }}</text><text class="meta">购买日期 {{ dateText(row.purchaseDate) }}</text></view><text class="amount">¥{{ money(row.totalAmount) }}</text></view>
      <view class="metrics"><text>购买 {{ quantity(row.purchaseQuantity) }}</text><text>赠送 {{ quantity(row.giftQuantity) }}</text><text class="paid">已收 ¥{{ money(row.paidAmount) }}</text><text class="debt">欠款 ¥{{ money(row.receivableAmount) }}</text></view>
      <view class="row-footer"><text>{{ paymentStatusText(row.paymentStatus) }} · {{ deliveryStatusText(row.deliveryStatus) }}</text><view class="row-buttons"><button @tap="openDetail(row)">查看</button><button v-if="can('edit')" @tap="openEdit(row)">编辑</button><button v-if="can('payment') && Number(row.receivableAmount) > 0" class="warn" @tap="openPayment(row)">收款</button><button v-if="can('delivery')" class="success" @tap="openDelivery(row)">领取</button><button v-if="can('return')" class="warn" @tap="openReturn(row)">退货</button><button v-if="can('cancel') && String(row.orderStatus) !== 'CANCELLED' && String(row.deliveryStatus) !== '2'" class="danger" @tap="cancel(row)">作废</button></view></view>
    </view>
    <view class="empty" v-if="!loading && !rows.length">暂无购买记录</view>

    <view class="mask" v-if="panel" @tap="closePanel"><view class="panel" @tap.stop>
      <view class="panel-title">{{ panelTitle }}</view>
      <template v-if="panel === 'detail' || panel === 'edit'">
        <view class="form-grid"><view class="field"><text>购买日期</text><picker mode="date" :value="form.purchaseDate" @change="form.purchaseDate=$event.detail.value"><view class="control">{{ form.purchaseDate || '请选择' }}</view></picker></view><view class="field"><text>顾客类型</text><picker :range="customerTypes" range-key="label" :value="customerTypeIndex" @change="selectCustomerType"><view class="control">{{ customerTypeText(form.customerType) }}</view></picker></view><view class="field full"><text>顾客姓名</text><input v-model="form.customerName" placeholder="请输入顾客姓名" /></view><view class="field full"><text>手机号（可不填）</text><input v-model="form.customerPhone" type="number" placeholder="请输入手机号" /></view></view>
        <view class="section-title">购买明细</view><view class="item-box"><view class="field full"><text>商品</text><picker :range="products" range-key="productName" :value="productIndex" @change="selectProduct"><view class="control">{{ selectedProduct?.productName || '请选择商品' }}</view></picker></view><view class="field"><text>购买数量</text><input v-model="form.item.purchaseQuantity" type="digit" placeholder="数量（最多3位小数）" @input="limit('purchaseQuantity', $event.detail.value, 3)" /></view><view class="field"><text>单价</text><input v-model="form.item.unitPrice" type="digit" placeholder="金额（2位小数）" @input="limit('unitPrice', $event.detail.value, 2)" /></view><view class="field"><text>赠送数量</text><input v-model="form.item.giftQuantity" type="digit" placeholder="非活动可填0" @input="limit('giftQuantity', $event.detail.value, 3)" /></view></view>
        <view class="field full"><text>备注</text><textarea v-model="form.remark" placeholder="备注，可不填" /></view><button v-if="panel === 'edit' && can('edit')" class="primary wide" @tap="saveEdit">保存编辑</button><button v-else-if="panel === 'detail'" class="secondary wide" @tap="closePanel">关闭</button>
        <view v-if="panel === 'detail'" class="history"><view class="section-title">收款记录</view><view v-for="p in detail.payments || []" :key="p.paymentId" class="history-row">{{ dateText(p.paymentDate) }} · {{ paymentMethodText(p.paymentMethod) }} · ¥{{ money(p.paymentAmount) }}</view><view class="section-title">领取记录</view><view v-for="d in detail.deliveries || []" :key="d.deliveryId" class="history-row">{{ dateText(d.deliveryDate) }} · {{ quantity(d.totalDeliveryQuantity) }} · {{ d.receiverName || '-' }}</view></view>
      </template>
      <template v-else-if="panel === 'create'"><view class="form-section"><view class="form-grid"><FormField :field="{ key: 'purchaseDate', label: '购买日期', type: 'date' }" required :value="form.purchaseDate" @set-value="form.purchaseDate = $event" /><view class="field"><text>顾客类型</text><picker :range="customerTypes" range-key="label" :value="customerTypeIndex" @change="selectCustomerType"><view class="control">{{ customerTypeText(form.customerType) }}</view></picker></view></view><view v-if="form.customerType === 'MEMBER'" class="member-search-section"><view class="member-search-header"><text class="section-title">会员查找</text><text class="member-search-hint">支持编号、姓名或手机号</text></view><view class="member-search-row"><input class="member-search-input" v-model="memberKeyword" confirm-type="search" placeholder="输入会员编号、姓名或手机号" @confirm="searchMembers" /><button class="member-search-btn" @tap="searchMembers">搜索</button></view><view v-if="form.memberId" class="selected-member"><view><text class="selected-member-name">{{ form.memberName || '-' }}</text><text class="selected-member-no">{{ form.memberNo || '-' }}</text></view><text class="selected-member-clear" @tap="clearMember">重新选择</text></view><view v-if="memberResults.length" class="member-result-list"><view class="member-result" v-for="member in memberResults" :key="member.memberId" @tap="selectMember(member)"><view><text class="member-result-name">{{ member.memberName || '-' }}</text><text class="member-result-no">{{ member.memberNo || '-' }}</text></view><text class="member-result-arrow">›</text></view></view><view class="member-result-empty" v-if="memberSearched && !memberLoading && !memberResults.length">未找到匹配会员</view></view><view class="form-grid"><view class="field"><text>顾客姓名</text><input v-model="form.customerName" placeholder="非会员可手工填写" /></view><view class="field"><text>手机号</text><input v-model="form.customerPhone" type="number" placeholder="可不填" /></view><view class="field full"><text>核算周期</text><picker :range="periods" range-key="label" :value="periodIndex" @change="selectPeriod"><view class="control">{{ selectedPeriod?.label || '请选择当前机构核算周期' }}</view></picker></view></view></view><view class="form-section"><view class="section-title">首个购买明细</view><view class="item-box"><view class="field full"><text>商品</text><picker :range="products" range-key="productName" :value="productIndex" @change="selectProduct"><view class="control">{{ selectedProduct?.productName || '请选择商品' }}</view></picker></view><view class="field full"><text>销售政策（可选）</text><picker :range="policies" range-key="policyName" :value="policyIndex" @change="selectPolicy"><view class="control">{{ selectedPolicy?.policyName || '不参加活动，按单价购买' }}</view></picker></view><view v-if="packages.length" class="field full"><text>购买套餐（可选）</text><picker :range="packages" range-key="label" :value="packageIndex" @change="selectPackage"><view class="control">{{ selectedPackage?.label || '请选择套餐档位' }}</view></picker></view><view class="field"><text>购买数量</text><input v-model="form.item.purchaseQuantity" type="digit" placeholder="最多3位小数" @input="limit('purchaseQuantity', $event.detail.value, 3)" /></view><view class="field"><text>单价</text><input v-model="form.item.unitPrice" type="digit" placeholder="手工输入，2位小数" @input="limit('unitPrice', $event.detail.value, 2)" /></view><view class="field"><text>赠送数量</text><input v-model="form.item.giftQuantity" type="digit" placeholder="可填0" @input="limit('giftQuantity', $event.detail.value, 3)" /></view></view><button class="primary wide" @tap="saveCreate">保存购买单</button></view></template>
      <template v-else-if="panel === 'payment'"><view class="field full"><text>剩余应收</text><view class="readonly">¥{{ money(active.receivableAmount) }}</view></view><view class="field full"><text>本次收款金额</text><input v-model="paymentForm.paymentAmount" type="digit" placeholder="2位小数" @input="limitPayment" /></view><view class="field full"><text>收款方式</text><picker :range="paymentMethods" range-key="label" :value="paymentIndex" @change="paymentIndex=Number($event.detail.value)"><view class="control">{{ paymentMethods[paymentIndex]?.label || '请选择' }}</view></picker></view><button class="primary wide" @tap="savePayment">确认收款</button></template>
      <template v-else><view class="field full"><text>商品明细</text><picker :range="deliveryItems" range-key="label" :value="deliveryIndex" @change="selectDeliveryItem"><view class="control">{{ deliveryItems[deliveryIndex]?.label || '请选择' }}</view></picker></view><view class="field"><text>销售领取</text><input v-model="deliveryForm.saleDeliveryQuantity" type="digit" placeholder="最多3位小数" /></view><view class="field"><text>赠品领取</text><input v-model="deliveryForm.giftDeliveryQuantity" type="digit" placeholder="最多3位小数" /></view><view class="field full"><text>领取人</text><input v-model="deliveryForm.receiverName" placeholder="请输入领取人" /></view><button class="primary wide" @tap="saveDelivery">确认领取</button></template>
    </view></view>
  </view>
</template>

<script>
import { request } from '@/api/index.js'
import FormField from '@/pages/form/form-modules/FormField.vue'
import { hasActionPermission, requireModuleOrActionPermission } from '@/utils/permission.js'
import { resolveMemberSearchField } from '@/utils/memberWorkflow.js'
import { workContext } from '@/utils/workContext.js'

const newPurchaseForm = () => ({ purchaseDate: '', periodId: '', customerType: 'MEMBER', customerName: '', customerPhone: '', remark: '', item: { productId: '', purchaseQuantity: '', unitPrice: '', giftQuantity: '' } })

export default {
  components: { FormField },
  data() { return { authorized: false, currentDeptName: '', currentDeptId: '', rows: [], loading: false, keyword: '', panel: '', detail: {}, active: {}, form: newPurchaseForm(), products: [], periods: [], policies: [], memberKeyword: '', memberResults: [], memberLoading: false, memberSearched: false, paymentMethods: [{ label: '现金', value: 'CASH' }, { label: '微信支付', value: 'WECHAT' }, { label: '支付宝', value: 'ALIPAY' }, { label: '银行转账', value: 'BANK' }, { label: '其他', value: 'OTHER' }], paymentIndex: 0, paymentForm: { paymentAmount: '' }, deliveryItems: [], deliveryIndex: 0, deliveryForm: { saleDeliveryQuantity: '', giftDeliveryQuantity: '', receiverName: '' } } },
  computed: { panelTitle() { return ({ create: '新建购买单', detail: '购买单详情', edit: '编辑购买单', payment: '登记收款', delivery: '登记领取' })[this.panel] }, customerTypes() { return [{ label: '会员', value: 'MEMBER' }, { label: '非会员', value: 'CUSTOMER' }, { label: '散客', value: 'WALK_IN' }] }, customerTypeIndex() { const i = this.customerTypes.findIndex(x => x.value === this.form.customerType); return i < 0 ? 0 : i }, productIndex() { const i = this.products.findIndex(x => String(x.productId) === String(this.form.item.productId)); return i < 0 ? 0 : i }, periodIndex() { const i = this.periods.findIndex(x => String(x.periodId) === String(this.form.periodId)); return i < 0 ? 0 : i }, policyIndex() { const i = this.policies.findIndex(x => String(x.policyId) === String(this.form.item.policyId)); return i < 0 ? 0 : i }, packages() { return (this.policies[this.policyIndex]?.packages || []).map((x, i) => ({ ...x, label: `${x.packageName || `档位${i + 1}`}：买${this.quantity(x.purchaseQuantity)}送${this.quantity(x.giftQuantity)} · ¥${this.money(x.packagePrice)}` })) }, packageIndex() { const i = this.packages.findIndex(x => String(x.packageId) === String(this.form.item.packageId)); return i < 0 ? 0 : i }, selectedProduct() { return this.products[this.productIndex] }, selectedPolicy() { return this.policies[this.policyIndex] }, selectedPackage() { return this.packages[this.packageIndex] }, selectedPeriod() { return this.periods[this.periodIndex] } },
  onLoad() { this.authorized = requireModuleOrActionPermission('memberPurchase'); const scope = workContext.snapshot(); this.currentDeptId = scope.currentDeptId; this.currentDeptName = scope.currentDept?.name || scope.currentDept?.deptName || '未选择机构'; if (this.authorized) { this.loadOptions(); this.load() } },
  methods: {
    emptyForm() { return { ...newPurchaseForm(), purchaseDate: this.today() } },
    can(action) { return hasActionPermission('memberPurchase', action) }, today() { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}` }, isoDateTime(value) { if (!value) return new Date().toISOString(); const text = String(value); if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return new Date(`${text}T00:00:00`).toISOString(); return new Date(text.replace(' ', 'T')).toISOString() }, dateText(v) { return v ? String(v).replace('T',' ').slice(0,19) : '-' }, money(v) { return Number(v || 0).toFixed(2) }, quantity(v) { return Number(v || 0).toFixed(3).replace(/\.0+$/, '').replace(/(\.\d*?)0+$/, '$1') }, customerTypeText(v) { return ({ MEMBER: '会员', CUSTOMER: '非会员', WALK_IN: '散客' })[v] || v || '-' }, paymentStatusText(v) { return ({ '0':'未收款','1':'部分收款','2':'已收清','3':'已退款' })[String(v)] || '未知' }, deliveryStatusText(v) { return ({ '0':'未领取','1':'部分领取','2':'全部领取' })[String(v)] || '未知' }, paymentMethodText(v) { return this.paymentMethods.find(x => x.value === v)?.label || ({ WECHAT:'微信支付', ALIPAY:'支付宝', CASH:'现金', BANK:'银行转账' })[v] || v || '-' },
    unwrap(res) { return res?.rows || res?.data?.rows || res?.data || [] }, async loadOptions() { const [p, a] = await Promise.all([request({ url:'/finance/product/list', method:'GET', data:{ pageNum:1, pageSize:200, deptId:this.currentDeptId } }), request({ url:'/finance/accountingPeriod/list', method:'GET', data:{ pageNum:1, pageSize:200, deptId:this.currentDeptId } })]); this.products = this.unwrap(p); this.periods = this.unwrap(a).filter(x => String(x.deptId) === String(this.currentDeptId)).map(x => ({ ...x, label: `${x.periodNo || x.periodId}（${this.dateText(x.startTime)} 至 ${x.endTime ? this.dateText(x.endTime) : '当前'}）` })); if (this.form.item.productId && this.form.periodId) await this.loadPolicies() }, async loadPolicies() { if (!this.form.item.productId || !this.form.periodId) { this.policies = []; return }; const res = await request({ url:'/member/campaign/policy/list', method:'GET', data:{ pageNum:1, pageSize:200, deptId:this.currentDeptId, productId:this.form.item.productId, periodId:this.form.periodId, status:'1' } }); const rows = this.unwrap(res).filter(x => String(x.productId) === String(this.form.item.productId) && String(x.periodId) === String(this.form.periodId)); const detailed = await Promise.all(rows.map(async (policy) => { if (Array.isArray(policy.packages) && policy.packages.length) return policy; try { const detail = await request({ url:`/member/campaign/policy/${policy.policyId}`, method:'GET' }); return detail?.data || detail || policy } catch (e) { return policy } })); this.policies = [{ policyId:'', policyName:'不参加活动，按单价购买', packages:[] }, ...detailed] }, async load() { this.loading = true; try { const res = await request({ url:'/member/purchase/list', method:'GET', data:{ pageNum:1, pageSize:50, deptId:this.currentDeptId, customerName:this.keyword || undefined } }); this.rows = this.unwrap(res) } finally { this.loading = false } },
    selectCustomerType(e) { this.form.customerType = this.customerTypes[Number(e.detail.value)].value; if (this.form.customerType !== 'MEMBER') { this.form.memberId = ''; this.memberKeyword = ''; this.memberResults = [] } }, async searchMembers() { const keyword = String(this.memberKeyword || '').trim(); if (!keyword) return uni.showToast({ title:'请输入会员编号、姓名或手机号', icon:'none' }); this.memberLoading = true; this.memberSearched = true; try { const key = resolveMemberSearchField(keyword); const res = await request({ url:'/member/member/list', method:'GET', data:{ pageNum:1, pageSize:20, deptId:this.currentDeptId, [key]:keyword } }); this.memberResults = this.unwrap(res) } finally { this.memberLoading = false } }, selectMember(member) { this.form.memberId = member?.memberId || ''; this.form.memberNo = member?.memberNo || ''; this.form.memberName = member?.memberName || ''; this.form.customerName = member?.memberName || ''; this.form.customerPhone = member?.phone || ''; this.memberKeyword = `${member?.memberNo || ''} ${member?.memberName || ''}`.trim(); this.memberResults = [] }, clearMember() { this.form.memberId = ''; this.form.memberNo = ''; this.form.memberName = ''; this.memberKeyword = '' }, selectProduct(e) { this.form.item.productId = this.products[Number(e.detail.value)]?.productId || ''; this.form.item.policyId = ''; this.form.item.packageId = ''; this.form.item.giftQuantity = ''; this.loadPolicies() }, selectPolicy(e) { const policy = this.policies[Number(e.detail.value)]; this.form.item.policyId = policy?.policyId || ''; this.form.item.packageId = ''; if (policy?.packages?.length === 1) this.selectPackage({ detail: { value: 0 } }) }, selectPackage(e) { const pkg = this.packages[Number(e.detail.value)]; this.form.item.packageId = pkg?.packageId || ''; if (pkg) { this.form.item.purchaseQuantity = this.quantity(pkg.purchaseQuantity); this.form.item.giftQuantity = this.quantity(pkg.giftQuantity); this.form.item.unitPrice = this.money(Number(pkg.packagePrice || 0) / Number(pkg.purchaseQuantity || 1)) } }, selectPeriod(e) { this.form.periodId = this.periods[Number(e.detail.value)]?.periodId || ''; this.loadPolicies() }, limit(key, value, precision) { const s = String(value || '').replace(/[^\d.]/g,'').replace(/\.(?=.*\.)/g,''); this.form.item[key] = s.includes('.') ? s.split('.')[0] + '.' + s.split('.')[1].slice(0, precision) : s }, limitPayment(e) { this.paymentForm.paymentAmount = String(e.detail.value || '').replace(/[^\d.]/g,'').replace(/\.(?=.*\.)/g,'').replace(/(\.\d{2}).*/,'$1') },
    openCreate() { this.form = this.emptyForm(); this.memberKeyword = ''; this.memberResults = []; this.memberSearched = false; this.panel = 'create' }, openReturn(row) { uni.navigateTo({ url:`/pages/member-purchase-return/index?purchaseId=${row.purchaseId}` }) }, async openDetail(row) { const res = await request({ url:`/member/purchase/${row.purchaseId}`, method:'GET' }); this.detail = res.data || res; this.form = { ...this.emptyForm(), ...this.detail, item: { ...(this.detail.items?.[0] || {}) } }; this.active = row; this.panel = 'detail' }, async openEdit(row) { await this.openDetail(row); this.panel = 'edit' }, closePanel() { this.panel = '' },
    async saveCreate() { const f = this.form; if (!f.periodId || !f.item.productId || Number(f.item.purchaseQuantity) <= 0 || Number(f.item.unitPrice) <= 0) return uni.showToast({ title:'请完整填写周期、商品、数量和单价', icon:'none' }); if (f.customerType === 'MEMBER' && !f.memberId) return uni.showToast({ title:'请选择会员', icon:'none' }); await request({ url:'/member/purchase', method:'POST', data:{ ...f, identityConfirmed:false, purchaseDate:this.isoDateTime(f.purchaseDate), items:[{ ...f.item, giftQuantity:Number(f.item.giftQuantity || 0) }], idempotencyKey:`mp-purchase-${Date.now()}` } }); uni.showToast({ title:'购买单已保存', icon:'success' }); this.closePanel(); this.load() },
    async saveEdit() { await request({ url:`/member/purchase/${this.detail.purchaseId}`, method:'PUT', data:{ customerName:this.form.customerName, customerPhone:this.form.customerPhone, purchaseDate:this.form.purchaseDate, remark:this.form.remark, items:[this.form.item] } }); uni.showToast({ title:'购买单已保存', icon:'success' }); this.closePanel(); this.load() },
    async openPayment(row) { this.active = row; this.paymentForm = { paymentAmount: this.money(row.receivableAmount) }; this.paymentIndex = 0; this.panel = 'payment' }, async savePayment() { const n = Number(this.paymentForm.paymentAmount); if (!(n > 0) || n > Number(this.active.receivableAmount || 0)) return uni.showToast({ title:'收款金额必须大于0且不能超过欠款', icon:'none' }); await request({ url:`/member/purchase/${this.active.purchaseId}/payment`, method:'POST', data:{ paymentAmount:n, paymentMethod:this.paymentMethods[this.paymentIndex].value, paymentDate:this.isoDateTime(this.today()), idempotencyKey:`mp-payment-${Date.now()}` } }); uni.showToast({ title:'收款成功', icon:'success' }); this.closePanel(); this.load() },
    async openDelivery(row) { const res = await request({ url:`/member/purchase/${row.purchaseId}`, method:'GET' }); const d = res.data || res; this.active = row; this.deliveryItems = (d.items || []).map(x => ({ ...x, label:`${x.productNameSnapshot || '商品'}（待领取${this.quantity(x.remainingQuantity)}）` })).filter(x => Number(x.remainingQuantity || 0) > 0); this.deliveryIndex = 0; const first = this.deliveryItems[0]; this.deliveryForm = { saleDeliveryQuantity:this.quantity(Math.max(0, Number(first?.purchaseQuantity || 0) - Number(first?.deliveredSaleQuantity || 0))), giftDeliveryQuantity:this.quantity(Math.max(0, Number(first?.giftQuantity || 0) - Number(first?.deliveredGiftQuantity || 0))), receiverName:d.customerName || '' }; this.panel = 'delivery' }, selectDeliveryItem(e) { this.deliveryIndex = Number(e.detail.value); const item = this.deliveryItems[this.deliveryIndex]; this.deliveryForm.saleDeliveryQuantity = this.quantity(Math.max(0, Number(item?.purchaseQuantity || 0) - Number(item?.deliveredSaleQuantity || 0))); this.deliveryForm.giftDeliveryQuantity = this.quantity(Math.max(0, Number(item?.giftQuantity || 0) - Number(item?.deliveredGiftQuantity || 0))) }, async saveDelivery() { const item = this.deliveryItems[this.deliveryIndex]; const sale = Number(this.deliveryForm.saleDeliveryQuantity || 0); const gift = Number(this.deliveryForm.giftDeliveryQuantity || 0); const saleRemaining = Number(item?.purchaseQuantity || 0) - Number(item?.deliveredSaleQuantity || 0); const giftRemaining = Number(item?.giftQuantity || 0) - Number(item?.deliveredGiftQuantity || 0); if (!item || sale + gift <= 0 || sale > saleRemaining || gift > giftRemaining) return uni.showToast({ title:'领取数量不能超过剩余可领取数量', icon:'none' }); await request({ url:`/member/purchase/${this.active.purchaseId}/delivery`, method:'POST', data:{ itemId:item.itemId, saleDeliveryQuantity:sale, giftDeliveryQuantity:gift, totalDeliveryQuantity:sale+gift, deliveryDate:this.isoDateTime(this.today()), receiverName:this.deliveryForm.receiverName, idempotencyKey:`mp-delivery-${Date.now()}` } }); uni.showToast({ title:'领取成功', icon:'success' }); this.closePanel(); this.load() },
    async cancel(row) { const ok = await new Promise(resolve => uni.showModal({ title:'确认作废', content:`确认作废购买单 ${row.purchaseNo}？`, success:r=>resolve(r.confirm) })); if (!ok) return; await request({ url:`/member/purchase/${row.purchaseId}/cancel`, method:'PUT' }); uni.showToast({ title:'购买单已作废', icon:'success' }); this.load() }
  }
}
